Lemma cmp_run (fx : FPState) R M (pc : Z) (W0 W1 W2 W3 W4 W5 W6 : bv 32) (i2 i5 : bv 13) (i4 : bv 21) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W0 -> is_ecall W0 = false -> decode_any W0 = Some (OpImm ALU_SLTU 14 14 1, 4%Z) ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 4)) = Some W1 -> is_ecall W1 = false -> decode_any W1 = Some (Op ALU_SRL 14 15 14, 4%Z) ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 8)) = Some W2 -> is_ecall W2 = false -> decode_any W2 = Some (Branch BC_GEU 14 11 i2, 4%Z) -> bv_signed i2 = 12 ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 12)) = Some W3 -> is_ecall W3 = false -> decode_any W3 = Some (OpImm ALU_ADD 11 0 7, 4%Z) ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 16)) = Some W4 -> is_ecall W4 = false -> decode_any W4 = Some (Jal 0 i4, 4%Z) -> bv_signed i4 = 12 ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 20)) = Some W5 -> is_ecall W5 = false -> decode_any W5 = Some (Branch BC_GEU 11 14 i5, 4%Z) -> bv_signed i5 = 228 ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 24)) = Some W6 -> is_ecall W6 = false -> decode_any W6 = Some (OpImm ALU_ADD 11 0 6, 4%Z) ->
  0 <= pc -> pc + 256 < 2 ^ 64 ->
  exists R', (forall x : nat, (x < 32)%nat -> x <> 11%nat -> x <> 14%nat -> getr R' (Z_to_bv 5 (Z.of_nat x)) = getr R (Z_to_bv 5 (Z.of_nat x)))
    /\ ( (msteps RSEGS (st fx R pc M) (st fx R' (pc + 28) M) /\ (getr R' 11%bv = Z_to_bv 64 7 \/ getr R' 11%bv = Z_to_bv 64 6))
         \/ (msteps RSEGS (st fx R pc M) (st fx R' (pc + 248) M) /\ getr R' 11%bv = getr R 11%bv) ).
Proof.
