Lemma cmp_run_EA fx R M : exists R', (forall x : nat, (x < 32)%nat -> x <> 11%nat -> x <> 14%nat -> getr R' (Z_to_bv 5 (Z.of_nat x)) = getr R (Z_to_bv 5 (Z.of_nat x)))
    /\ ( (msteps RSEGS (st fx R 0xc2c1c M) (st fx R' 0xc2c38 M) /\ (getr R' 11%bv = Z_to_bv 64 7 \/ getr R' 11%bv = Z_to_bv 64 6))
