Section Run.
Hypothesis PMODE : NESKA.spa_mode P.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (V2 cls r ov osk oec cat : Z).
Variables (en : enc) (k : NESK.sink) (b e : bool) (ea : NECS.eargs).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 128).
Local Notation SCR := (PMSPA.pm_scr 4).
(* [comment removed for export] *)
Local Notation BX0 := (enc_own en).
Local Notation LBXg := (NESK.sink_own k ++ LBX).
Local Notation W := (NECS.W_enc AD ov osk oec).
Hypothesis Hcls : cls = 0 \/ cls = 16.
Hypothesis V32 : V2 mod 32 = 0.
Hypothesis HH : ri_inv HI (BX0 ++ LBXg) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r 4.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM 4 FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis A10 : getr R 10%bv = Z_to_bv 64 ov.
Hypothesis A12 : getr R 12%bv = Z_to_bv 64 oec.
Hypothesis AOov : PMSPA.aobjA FF ov 56.
Hypothesis ALov : ov mod 8 = 0.
Hypothesis AOosk : PMSPA.aobjA FF osk 24.
Hypothesis ALosk : osk mod 8 = 0.
Hypothesis AOoec : PMSPA.aobjA FF oec 16.
Hypothesis ALoec : oec mod 8 = 0.
Hypothesis SEP1 : ov + 56 <= osk \/ osk + 24 <= ov.
Hypothesis SEP2 : oec + 16 <= ov \/ ov + 56 <= oec.
Hypothesis SEP3 : oec + 16 <= osk \/ osk + 24 <= oec.
Hypothesis EA : enc_atA M ov osk en.
Hypothesis SKA : sink_atA M osk k.
Hypothesis ECS : ec_stateA M oec b cat.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis ERR : PQSTA.err_okA RSEGS AD AAD AQ M e.
Hypothesis PRED : 1 <= en_depth en.
Hypothesis CRED : PMSP.credit_le (NECSA.pot_encA L ar P en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
                         (en' : enc) (k' : NESK.sink) (b' e' : bool) (cr' : credit),
        regs_preserved R R' ->
        enc_atA M' ov osk en' -> sink_atA M' osk k' -> ec_stateA M' oec b' cat -> PMSTA.base_okA RSEGS AD M' -> PQSTA.err_okA RSEGS AD AAD AQ M' e' ->
        (b = true -> b' = true) -> (e = true -> e' = true) -> NECS.step_end ea en k b en' k' b' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 4) W M M' ->
        PMSP.credit_keep cr cr' (NECSA.pot_encA L ar P en k) (NECSA.pot_encA L ar P en' k') ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (NECS.eown en' k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx') R' r M' model') K.

