Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Lemma ofacts M3 model3 LK3 Aw3 (en1 : enc) :
  GM BX0 M3 model3 LK3 Aw3 cr -> enc_atA M3 ov osk en1 -> en_b en1 = en_b en -> en_k en1 = en_k en ->
  let MV := mrestrict (ahid Aw3 model3) M3 in let eb := en_b en1 in let ed := en_b en1 + 24 * en_n en1 in
  (7036928 <= ov /\ ov + 56 <= ahl_ceil ar /\ ov + 56 <= 2 ^ 47 /\ (2147446784 + 17592186048512 <= ov \/ ov + 56 <= 2147446784))
  /\ (L5KA.zeros_at MV (ov / 8 + SBL) 7 /\ L5.writable RSEGS MV ov 56
      /\ L5.u64_at RSEGS MV (ov + 24) eb /\ L5.u64_at RSEGS MV (ov + 32) ed /\ L5.u32_at RSEGS MV (ov + 48) (en_depth en1)
      /\ L5KA.zeros_at MV ((ov + 24) / 8 + SBL) 1 /\ L5KA.zeros_at MV ((ov + 32) / 8 + SBL) 1 /\ L5KA.zeros_at MV ((ov + 48) / 8 + SBL) 1)
  /\ (0 < en_k en1 -> 4096 <= eb /\ eb + 24 * ecap (en_k en1) <= 2 ^ 47 /\ eb mod 16 = 0 /\ (2147446784 + 17592186048512 <= eb \/ eb + 24 * ecap (en_k en1) <= 2147446784)
      /\ In (eb, 24 * ecap (en_k en1)) (BX0 ++ LBXg) /\ eb + 24 * ecap (en_k en1) <= ahl_ceil ar
      /\ (forall a n0, eb <= a -> a + n0 <= eb + 24 * ecap (en_k en1) -> avis (ahid Aw3 model3) a n0)
      /\ (forall a, eb <= a -> a + 8 <= eb + 24 * en_n en1 -> a mod 8 = 0 -> L5KA.zeros_at MV (a / 8 + SBL) 1)
      /\ L5.writable RSEGS MV eb (24 * ecap (en_k en1)))
  /\ (ov + 56 <= F \/ F + 128 <= ov) /\ (forall j, 0 <= j < 7 -> ov / 8 + SBL + j + 1 <= F / 8 + SBL \/ F / 8 + SBL + 16 <= ov / 8 + SBL + j)
  /\ (0 < en_k en1 -> (eb + 24 * ecap (en_k en1) <= F \/ F + 128 <= eb) /\ (eb + 24 * ecap (en_k en1) <= ov \/ ov + 56 <= eb)).
Proof.
